insert into public.solutions (slug, menu_group, card_group, title_en, title_fr, tagline_en, tagline_fr, summary_en, summary_fr, image_url, sort_order, status, is_core)
values
  ('digital-infrastructure', 'technology', 'infrastructure', 'Digital Infrastructure', 'Infrastructure numérique', 'Enterprise networking • Data centers • Storage', 'Réseaux d’entreprise • Centres de données • Stockage', 'Build a resilient technology foundation for critical services and everyday operations.', 'Construire une base technologique résiliente pour les services critiques et les opérations quotidiennes.', 'img/digital-transformation-hero-card.jpg', 10, 'published', true),
  ('cloud-modern-workplace', 'technology', 'infrastructure', 'Cloud & Modern Workplace', 'Cloud et environnement de travail moderne', 'Cloud infrastructure • Hybrid environments', 'Infrastructure cloud • Environnements hybrides', 'Plan and operate cloud environments with appropriate security, governance and cost oversight.', 'Planifier et exploiter des environnements cloud avec une sécurité, une gouvernance et un contrôle des coûts appropriés.', 'img/cloud-modern-workplace-hero-card.jpg', 20, 'published', true),
  ('power-energy', 'connected', 'infrastructure', 'Power & Energy', 'Énergie et alimentation électrique', 'UPS • Solar • Backup • Data center power', 'Onduleurs • Solaire • Secours • Énergie des centres de données', 'Protect the availability of critical ICT systems with resilient power infrastructure.', 'Protéger la disponibilité des systèmes TIC critiques grâce à une alimentation électrique résiliente.', 'img/power-energy-hero-card.jpg', 30, 'published', true),
  ('cybersecurity', 'technology', 'security', 'Cybersecurity', 'Cybersécurité', 'Secure infrastructure • Identity • Protection', 'Infrastructures sécurisées • Identité • Protection', 'Protect users, systems and information with security designed around organizational risk.', 'Protéger les utilisateurs, les systèmes et les informations grâce à une sécurité adaptée aux risques de l’organisation.', 'img/cybersecurity-hero-card.jpg', 40, 'published', true),
  ('physical-security', 'connected', 'security', 'Physical Security', 'Sécurité physique', 'Surveillance • Access • Biometrics • Screening', 'Vidéosurveillance • Accès • Biométrie • Contrôle', 'Bring surveillance, access management and screening together to protect people and facilities.', 'Réunir la vidéosurveillance, la gestion des accès et l’inspection afin de protéger les personnes et les installations.', 'img/physical-security-hero-card.jpg', 50, 'published', true),
  ('managed-ict', 'connected', 'security', 'Managed ICT Services', 'Services TIC gérés', 'Monitoring • Maintenance • Service desk • Support', 'Supervision • Maintenance • Assistance • Support', 'Keep technology dependable through ongoing operational support and maintenance.', 'Assurer la fiabilité des technologies par un support opérationnel et une maintenance continus.', 'img/managed-ict-hero-card.jpg', 60, 'published', true),
  ('software-engineering', 'technology', 'applications', 'Software Engineering', 'Ingénierie logicielle', 'Custom development • Integration • Platforms', 'Développement sur mesure • Intégration • Plateformes', 'Create and connect digital applications that support the way an organization works.', 'Créer et connecter des applications numériques adaptées au fonctionnement de chaque organisation.', 'img/software-engineering-hero-card.jpg', 70, 'published', true),
  ('ai-digital-transformation', 'technology', 'applications', 'AI & Digital Transformation', 'IA et transformation numérique', 'Artificial intelligence • Analytics • Automation', 'Intelligence artificielle • Analytique • Automatisation', 'Apply data and automation to improve decisions, service delivery and operational efficiency.', 'Utiliser les données et l’automatisation pour améliorer les décisions, les services et l’efficacité opérationnelle.', 'img/ai-digital-transformation-hero-card.jpg', 80, 'published', true),
  ('iot-smart-solutions', 'connected', 'applications', 'IoT & Smart Solutions', 'IoT et solutions intelligentes', 'Smart buildings • Agriculture • Energy • Tracking', 'Bâtiments intelligents • Agriculture • Énergie • Suivi', 'Connect assets and environments to improve monitoring, insight and operational control.', 'Connecter les actifs et les environnements pour améliorer la supervision, la visibilité et le contrôle opérationnel.', 'img/iot-smart-solutions-hero-card.jpg', 90, 'published', true),
  ('banking-technology', 'connected', 'applications', 'Banking Technology', 'Technologies bancaires', 'Core banking • Payments • Digital banking', 'Banque centrale • Paiements • Banque numérique', 'Support secure, dependable financial services infrastructure and digital channels.', 'Soutenir des infrastructures de services financiers sécurisées et fiables ainsi que des canaux numériques.', 'img/banking-solutions-hero-card.jpg', 100, 'published', true),
  ('ict-consultancy', 'connected', 'advisory', 'ICT Consultancy & Professional Services', 'Conseil et services professionnels TIC', 'Strategy • Architecture • Assessment', 'Stratégie • Architecture • Évaluation', 'Make technology investments align with business objectives, risk and delivery capacity.', 'Aligner les investissements technologiques sur les objectifs métier, les risques et les capacités de réalisation.', 'img/ict-consultancy-hero-card.jpg', 110, 'published', true)
